package com.javatechie.entity;
import com.javatechie.utils.enums.BookingStatus;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.Instant;
import java.util.List;

@Entity
@Data
@AllArgsConstructor
@NoArgsConstructor
public class Booking {
  /*
   * Internal key generated by the database (was System.currentTimeMillis(): two requests in the same ms collided).
   * MySQL has no sequences, so Hibernate emulates this one with a "booking_seq" table; allocationSize = 50 ids per
   * round trip. This works with the existing id column (IDENTITY would need ALTER TABLE ... AUTO_INCREMENT).
   */
  @Id
  @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "booking_seq")
  @SequenceGenerator(name = "booking_seq", sequenceName = "booking_seq", allocationSize = 50)
  private Long id;

  // Public id (used in events, Kafka key, API): full random UUID instead of its first 8 hex chars
  @Column(unique = true, nullable = false, updatable = false, length = 36)
  private String bookingCode;
  private String showId;
  @ElementCollection
  private List<String> seatIds;
  private String userId;
  @Enumerated(EnumType.STRING)
  private BookingStatus status; // PENDING -> SEATS_LOCKED -> CONFIRMED, or FAILED
  private Instant createdAt;
  private long amount;

  // Client-supplied Idempotency-Key header; the unique constraint also stops two concurrent requests with the same key
  @Column(unique = true, length = 100, updatable = false)
  private String idempotencyKey;

  // seat-reserved-topic and payment-events are consumed on different threads and both update this row:
  // optimistic locking turns a lost update into a retry (DEFAULT 0 so ddl-auto can add it to existing rows)
  @Version
  @Column(columnDefinition = "BIGINT NOT NULL DEFAULT 0")
  private Long version;

  }
